def search_desc(target):
    start, end = 0, len(age) - 1
    while start <= end:
        mid = (start + end) // 2
        if age[mid] == target:
            return mid
        elif age[mid] > target:
            start = mid + 1
        else:
            end = mid - 1
    return -1
