keywords = ["and", "as", "def", "elif", "else", "for", "if", "while"]
def is_keyword(name):
    start, end = 0, len(keywords) - 1
    while start <= end:
        mid = (start + end) // 2
        if keywords[mid] == name:
            return True
        elif name < keywords[mid]:
            end = mid - 1
        else:
