def binary_search(a, target):
    start = 0
    end = len(a) - 1
    count = 0
    while start <= end:
        mid = (start + end) // 2
        count += 1
        if a[mid] == target:
            return (mid, count)
        elif target < a[mid]:
            end = mid - 1
        else:
            start = mid + 1
    return (-1, count)

